ifInstalled() {
  if [ -e ~/.local/share/applications/ncalayer.desktop ]; then
    #shellfile=`cat ~/.local/share/applications/ncalayer.desktop | grep -i Exec | cut -f2 -d'=' | cut -f1 -d' '`
    shellfile=`cat ~/.local/share/applications/ncalayer.desktop | grep -i Exec | cut -f2 -d'=' | cut -f2 -d'"'`
    if [ -e "$shellfile" ]; then
      echo "$shellfile"
    else
      echo
    fi
  else
    echo
  fi
}
ifRunning() {
  fname=`basename "$(ifInstalled)"`
  fbname=${fname%.*}
  status=$(ps aux | grep -e '\-jar' -e '$fbname' | grep -v 'grep.*-jar' | awk "{print \$2}");
  echo "$status"
}

killProc() {
  status=$(ifRunning);
  if [ ! "$status" ]; then
    :
  else
    name=`basename "$(ifInstalled)"`
    fbname=${fname%.*}
    kill $(ps aux | grep -e '\-jar' -e '$fbname' | grep -v 'grep.*-jar' | awk "{print \$2}");
  fi;
  
}

deleteTrustCert(){

  for certDB in $(find ~/ -name "cert8.db" 2>/dev/null)
  do
      certdir=$(dirname ${certDB});
      certutil -D -n "root_rsa.cer" -d dbm:${certdir} 2>/dev/null
      certutil -D -n "nca_rsa.cer"  -d dbm:${certdir} 2>/dev/null
  done

  for certDB in $(find ~/ -name "cert9.db" 2>/dev/null)
  do
      certdir=$(dirname ${certDB});
      certutil -D -n "root_rsa.cer" -d sql:${certdir} 2>/dev/null
      certutil -D -n "nca_rsa.cer"  -d sql:${certdir} 2>/dev/null
  done
}

uninstApp() {
  killProc
  sleep 3
  rm -f "$1" 2>/dev/null;
  xdg-desktop-icon uninstall --novendor ~/.local/share/applications/ncalayer.desktop 2>/dev/null
  rm -f ~/.local/share/applications/ncalayer.desktop 2>/dev/null;
  rm -f ~/.config/autostart/ncalayer.desktop 2>/dev/null;
  rm -f ~/.local/share/icons/ncalayer.png 2>/dev/null;
  rm -rf ~/.config/NCALayer 2>/dev/null
  rm -rf "$(dirname "$1")"/jre8_ncalayer 2>/dev/null;
  rm -f "$(dirname "$1")"/ncalayer.png 2>/dev/null;
  xdg-desktop-menu forceupdate
  kbuildsycoca4 2>/dev/null
  deleteTrustCert;
  if [ -z "$( ls -A "$(dirname "$1")" )" ]; then
    #echo "$(dirname "$1")"
    rm -rf "$(dirname "$1")" 2>/dev/null;
  fi
}

replTilda() {
  if [ -n "$1" ]; then
    userhome=`eval echo "~"`
    tilda=`echo "$1" | sed 's|~|'"$userhome"'|'` 
    echo "$tilda"
  else
    userhome=`eval echo "~"`
    echo "$userhome"
  fi
}

