createAutoExec() {
  if [ -d ~/.config/autostart ]; then
    if [ -w ~/.config/autostart/ncalayer.desktop ]; then
      rm -f ~/.config/autostart/ncalayer.desktop 2>/dev/null;
        if [ $? -ne 1 ]; then
          echo "${AUTOSTART_DATA}" > ~/.config/autostart/ncalayer.desktop
          echo "Exec=\""$1"/`basename "$0"`\" --run" >> ~/.config/autostart/ncalayer.desktop
          echo "0" #SUCCESS
        else
          echo "1" #ERROR
        fi
    else
      echo "${AUTOSTART_DATA}" > ~/.config/autostart/ncalayer.desktop
      echo "Exec=\""$1"/`basename "$0"`\" --run" >> ~/.config/autostart/ncalayer.desktop
      echo "0" #SUCCESS
    fi
  else
    if [ -w ~/.config/ ]; then
      mkdir -p ~/.config/autostart
      echo "${AUTOSTART_DATA}" > ~/.config/autostart/ncalayer.desktop
      echo "Exec=\""$1"/`basename "$0"`\" --run" >> ~/.config/autostart/ncalayer.desktop

      if [ $? -ne 0 ]; then
        echo "1" #ERRROR
      else
        echo "0" #SUCCESS
      fi
    fi
  fi
}

createIcon() {
base64=`whereis -b base64 | grep -i bin |  cut -d' ' -f2`;
if [ -x "$base64" ]; then

