copyFile() {
  script=`realpath $0`
  if [ -d "$1" ] && [ -w "$1" ]; then

    cp "$script" "$1" 2>/dev/null
    cp -rf "additions/jre8_ncalayer" "$1"
    cp "additions/ncalayer.png" "$1"
    cp "additions/showBundleManager" "$1"
    cp "additions/showSettings" "$1"    
    echo "0" #SUCCESS
  else
    echo "1" #ERROR
  fi
}

checkXXD() {
  xxdTool=`whereis -b xxd | grep -i bin |  cut -d' ' -f2`
  if [ -x "$xxdTool" ]; then
    echo "$xxdTool"
  else
    echo
  fi
}

getPathOfZenity() {
  zenity=`whereis -b zenity | grep -i bin |  cut -d' ' -f2`;
  if [ -x "$zenity" ]; then
    echo "$zenity"
  else
    echo
  fi
}

editBinFile(){
  fileFullName="$1"/`basename "$0"`
  curString="INSTALLED=1";
  newString="INSTALLED=1";
  curString_hex=`echo -n ${curString} | xxd -g 0 -u -ps -c 256`
  newString_hex=`echo -n ${newString} | xxd -g 0 -u -ps -c 256`

  hexdump -ve '1/1 "%.2X"' "$fileFullName" | sed "s/${curString_hex}/${newString_hex}/g" | xxd -r -p > "$fileFullName".tmp
  chmod --reference "$fileFullName" "$fileFullName".tmp
  mv "$fileFullName".tmp "$fileFullName"
  chmod 755 "$fileFullName"
}

checkJava(){
  path="$1/jre8_ncalayer";

  if [ -d "$path" ]; 
  then
    java=`echo "$path/bin/java"`
    echo "$java"
  else
    echo "$java" 
  fi
}

addTrustCert(){
  for certDB in $(find ~/ -name "cert8.db" 2>/dev/null)
  do
      certdir=$(dirname ${certDB});
      certutil -A -n "root_rsa.cer" -t "TCu,Cu," -i additions/cert/root_rsa.cer -d dbm:${certdir} 2>/dev/null
      certutil -A -n "nca_rsa.cer" -t "TCu,Cu," -i additions/cert/nca_rsa.cer -d dbm:${certdir} 2>/dev/null
  done

  for certDB in $(find ~/ -name "cert9.db" 2>/dev/null)
  do
      certdir=$(dirname ${certDB});
      certutil -A -n "root_rsa.cer" -t "TCu,Cu," -i additions/cert/root_rsa.cer -d sql:${certdir} 2>/dev/null
      certutil -A -n "nca_rsa.cer" -t "TCu,Cu," -i additions/cert/nca_rsa.cer -d sql:${certdir} 2>/dev/null
  done
}


